SELECT ?point ?tsid WHERE {
  ?p a brick:Equipment ;
     brick:hasTag "HWPump02" .
  ?p brick:hasPoint ?pt .
  ?pt ref:hasTimeseriesId ?tsid .
  ?pt a brick:Power ?maybe .
  BIND(?pt AS ?point)
}

SELECT ?pt ?tsid ?cls WHERE {
  ?p a brick:Equipment ;
     brick:hasTag "HWPump02" .
  ?pt ref:hasTimeseriesId ?tsid .
  ?pt a ?cls .
  FILTER (str(?pt) != str(?p))
}

